      body {
        margin: 0;
        min-height: 100vh;
        font-family:
          Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
          "Segoe UI", sans-serif;
        color: var(--text);
        background:
          radial-gradient(circle at top left, rgba(91, 108, 255, 0.18), transparent 34rem),
          linear-gradient(135deg, #fbfcff 0%, var(--bg) 55%, #eef3ff 100%);
      }

