        display: grid;
        gap: 18px;
        margin-bottom: 30px;
        text-align: center;
      }

      .eyebrow {
        width: fit-content;
        margin: 0 auto;
        padding: 8px 14px;
        border: 1px solid rgba(91, 108, 255, 0.25);
        border-radius: 999px;
        color: var(--accent-dark);
        background: rgba(255, 255, 255, 0.72);
        font-size: 0.82rem;
        font-weight: 700;
        letter-spacing: 0.08em;
        text-transform: uppercase;
      }

      h1 {
        max-width: 760px;
        margin: 0 auto;
        font-size: clamp(2.25rem, 6vw, 4.8rem);
        line-height: 0.98;
        letter-spacing: -0.06em;
