      .hero p {
        max-width: 660px;
        margin: 0 auto;
        color: var(--muted);
        font-size: clamp(1rem, 2vw, 1.2rem);
        line-height: 1.7;
      }

      .faq-shell {
        display: grid;
        gap: 14px;
        max-width: 860px;
        margin: 0 auto;
        padding: clamp(16px, 3vw, 28px);
