  <body>
    <main class="page" id="app"></main>

    <script>
      const faqs = [
        {
          question: "How often should I feed my cat?",
          answer:
            "Most adult cats do well with two measured meals per day, though kittens and cats with medical needs may require a different schedule. Follow your veterinarian's guidance and the feeding chart on your cat's food."
        },
        {
          question: "Why does my cat knead blankets or people?",
          answer:
            "Kneading is a normal comfort behavior that begins in kittenhood. Adult cats often knead when they feel relaxed, secure, or are preparing a soft spot to rest."
        },
        {
          question: "Do indoor cats need enrichment?",
          answer:
            "Yes. Indoor cats benefit from daily play, scratching surfaces, window perches, puzzle feeders, and places to climb or hide. Enrichment helps prevent boredom and supports healthy movement."
        },
        {
          question: "How can I tell if my cat is stressed?",
          answer:
            "Common signs include hiding more than usual, appetite changes, over-grooming, litter box changes, flattened ears, or increased vocalization. Sudden behavior changes should be discussed with a veterinarian."
        },
        {
          question: "Should cats have regular vet visits?",
          answer:
            "Routine wellness visits help catch health issues early and keep vaccines, dental care, parasite prevention, and weight management on track. Many adult cats should be seen at least once a year."
        }
      ];

      const escapeHtml = (value) =>
        value.replace(/[&<>"']/g, (character) => {
          const entities = {
            "&": "&amp;",
            "<": "&lt;",
            ">": "&gt;",
            '"': "&quot;",
            "'": "&#039;"
          };
          return entities[character];
        });

      const FAQItem = ({ question, answer }, index) => {
        const panelId = `faq-panel-${index + 1}`;
        const buttonId = `faq-button-${index + 1}`;

        return `
          <div class="example">
            <h2>
              <button
                class="faq-trigger"
                id="${buttonId}"
                type="button"
                aria-expanded="false"
                aria-controls="${panelId}"
              >
                <span>${escapeHtml(question)}</span>
                <span class="icon" aria-hidden="true">+</span>
              </button>
            </h2>
            <div
              class="details"
              id="${panelId}"
              role="region"
              aria-labelledby="${buttonId}"
              hidden
            >
              <p>${escapeHtml(answer)}</p>
            </div>
          </div>
        `;
      };

      const FAQList = ({ items }) => `
        <section class="faq-shell" aria-label="Cat care frequently asked questions">
          ${items.map(FAQItem).join("")}
        </section>
      `;

      const App = () => `
        <section class="hero" aria-labelledby="page-title">
          <p class="eyebrow">Cat care guide</p>
          <h1 id="page-title">Frequently asked questions about cats</h1>
          <p>
            Quick, practical answers for keeping cats comfortable, curious, and
            healthy at home.
          </p>
        </section>
        ${FAQList({ items: faqs })}
        <p class="footer-note">
          This guide is general information. Contact a veterinarian for advice
          about sudden behavior changes, illness, or individual care needs.
        </p>
      `;

      document.querySelector("#app").innerHTML = App();

      document.querySelectorAll(".faq-trigger").forEach((button) => {
        button.addEventListener("click", () => {
          const details = document.getElementById(button.getAttribute("aria-controls"));
          const isExpanded = button.getAttribute("aria-expanded") === "true";

          button.setAttribute("aria-expanded", String(!isExpanded));
          details.hidden = isExpanded;
        });
      });
    </script>
  </body>
</html>
