        overflow: hidden;
        border: 1px solid var(--border);
        border-radius: 18px;
        background: var(--surface);
        transition:
          border-color 180ms ease,
          box-shadow 180ms ease,
          transform 180ms ease;
      }

      .example:has(.faq-trigger[aria-expanded="true"]) {
        border-color: rgba(91, 108, 255, 0.42);
        box-shadow: 0 16px 34px rgba(91, 108, 255, 0.12);
      }

      .faq-trigger {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 18px;
        width: 100%;
        padding: 22px 24px;
        border: 0;
        color: inherit;
        background: transparent;
        font: inherit;
        font-size: 1.05rem;
        font-weight: 760;
        line-height: 1.35;
        text-align: left;
        cursor: pointer;
      }

      .faq-trigger:hover {
        background: var(--surface-soft);
      }

      .faq-trigger:focus-visible {
        outline: 4px solid rgba(91, 108, 255, 0.32);
        outline-offset: -4px;
      }

      .icon {
        display: grid;
        flex: 0 0 34px;
        width: 34px;
        height: 34px;
        place-items: center;
        border-radius: 50%;
        color: var(--accent-dark);
        background: #eef1ff;
        font-size: 1.35rem;
        font-weight: 600;
        line-height: 1;
        transition: transform 180ms ease;
      }

      .faq-trigger[aria-expanded="true"] .icon {
        transform: rotate(45deg);
