      .details {
        padding: 0 24px 24px;
        color: var(--muted);
        line-height: 1.75;
      }

      .details[hidden] {
        display: none;
      }

      .details p {
        margin: 0;
      }

      .footer-note {
        max-width: 720px;
        margin: 22px auto 0;
        color: var(--muted);
        font-size: 0.95rem;
        line-height: 1.6;
        text-align: center;
